import type { Database, Json } from "@/types/database";
import { resolveOutcome } from "@/lib/domain/settlement";
import { normalizeName } from "@/lib/domain/puzzle";
import type { QuestionType } from "@/lib/domain/types";
import { hoursFromNow } from "./now";

/**
 * The frozen world the demo runs on.
 *
 * ── Why a file and not a database ──────────────────────────────────────────
 *
 * DerbyUp closed in October 2026. What is left of it has to keep working on a
 * free static host, with no Postgres to pay for, no cron to keep alive and no
 * API-Football key to rotate — and it has to keep working in five years, with
 * nobody watching it. A seeded database would have satisfied none of that: it
 * would have needed hosting, it would have drifted as fixtures aged out, and
 * the first expired credential would have taken the whole product down.
 *
 * So the snapshot is source code. One file, one compile, one shape — and the
 * type checker is what keeps it honest, because every row below is declared as
 * the exact `Row<T>` the real schema generated. A column renamed in
 * `types/database.ts` breaks `npm run typecheck` here rather than producing a
 * page that renders `undefined` in production.
 *
 * ── Why everything is relative to DEMO_NOW ────────────────────────────────
 *
 * Nothing in this file states an absolute time. Kickoffs are offsets in hours
 * from `DEMO_NOW` (see `./now.ts`), so the eleven finished Premier League
 * matches stay finished, the two live ones stay live at the same minute, and
 * the eighteen open ones stay open — permanently. A dataset written with real
 * dates would have decayed into a screen full of matches that already happened
 * and a dashboard with nothing to predict.
 *
 * ── Why the derived values are derived and not typed in ───────────────────
 *
 * Three kinds of value here could have been written by hand and are not,
 * because a hand-written copy of a rule is a copy that can disagree with it:
 *
 *   · `questions.correct_outcome` comes from the real `resolveOutcome()`, given
 *     the final score on the row. A 2-2 therefore *cannot* be filed as a home
 *     win, and `over_under_2_5` cannot disagree with the goals in the score.
 *   · `bridge_players.normalized_name` comes from the real `normalizeName()`,
 *     so the autocomplete matches the same way the answer checker does.
 *   · `predictions.points_earned`, the profile totals and the demo user's
 *     achievements are generated by `scripts/build-demo-fixtures.mjs`, which
 *     imports the real `settlePrediction()` and the real `newlyEarned()` and
 *     runs them. The block is marked and must not be edited by hand; the
 *     numbers in it are the arithmetic the product would actually have done.
 *
 * What stays hand-written is everything editorial: which clubs played, what
 * the scores were, what the odds were, who the twelve players are, and every
 * word of Hebrew the advisor says. That part is judgement, not computation.
 *
 * ── Conventions worth knowing before reading on ───────────────────────────
 *
 *   · `games.home_team` / `away_team` hold the **provider's English spelling**,
 *     exactly as the fixtures sync wrote them, and the UI runs them through
 *     `translateTeam()`. Every name below is a real key in
 *     `lib/i18n/team-names.ts`, so every club renders in Hebrew.
 *   · `questions.outcomes[].label` for `match_result` is likewise the raw club
 *     name — `buildQuestions()` interpolates `game.home_team` — and
 *     `components/games/question-card.tsx` translates it at render time. The
 *     goals and BTTS labels are already Hebrew, because they are not names.
 *   · `advisor_insights.payload.recommendation.outcomeLabel` is the *Hebrew*
 *     name, because `buildAdvisorQuestions()` translates before `decorate()`
 *     stores it and `InsightCard` prints it verbatim. The two conventions look
 *     inconsistent and are not: they are two different layers.
 *   · ids are deterministic UUID v4 strings built by `demoId()`. They are
 *     valid v4 on purpose — several server actions validate ids with
 *     `z.string().uuid()` before they do anything else.
 */

type Row<T extends keyof Database["public"]["Tables"]> =
  Database["public"]["Tables"][T]["Row"];

// ─── Identity ──────────────────────────────────────────────────────────────

/**
 * Deterministic ids, one eight-hex-digit prefix per table.
 *
 * Shaped as real UUID v4 (`4` in the version nibble, `8` in the variant one)
 * because `lib/validation/schemas.ts` rejects anything else before an action
 * reaches its logic — a readable `"game-1"` would have failed at the door.
 */
function demoId(prefix: string, n: number): string {
  return `${prefix}-0000-4000-8000-${String(n).padStart(12, "0")}`;
}

const ID = {
  profile: "10000000",
  game: "20000000",
  question: "30000000",
  league: "50000000",
  member: "60000000",
  notification: "70000000",
  puzzle: "90000000",
  attempt: "a0000000",
  insight: "b0000000",
  dailyPick: "c0000000",
  conversation: "d0000000",
  message: "e0000000",
  player: "f0000000",
} as const;

/** Every player's id, so leagues and messages can name people rather than digits. */
