/**
 * The visitor *is* this person.
 *
 * Nothing authenticates, so every "my predictions", "my leagues" and
 * "my notifications" screen resolves to this id. It is exported rather than
 * inlined so there is exactly one answer to "who am I in the demo", and so a
 * page can say `userId === DEMO_USER_ID` instead of hard-coding a UUID.
 *
 * Noam is a plain member of the big league and the creator of the small one,
 * which is the combination that makes the most screens reachable: the league
 * table, the invite box, and the league-admin tab that only a creator sees.
 */
export const DEMO_USER_ID = PLAYER.noam;

