/** The first fixture id; the rest run on from it, as a provider's would. */
const FIRST_FIXTURE_ID = 1_412_301;

/** `GAME_ID["pl-mci-liv"]` — how everything else points at a fixture. */
export const GAME_ID: Record<string, string> = Object.fromEntries(
  GAME_SPECS.map((spec, index) => [spec.key, demoId(ID.game, index + 1)]),
);

/**
 * `settled_at` is kickoff plus 2.2 hours: ninety minutes of football, a
 * half-time break, stoppages, and the few minutes the settlement cron takes to
 * notice. A postponed fixture is "settled" half an hour after its slot, which
 * is when the provider reported the call-off and the job voided its
 * predictions.
 */
function settledAt(spec: GameSpec): string | null {
  if (spec.status === "finished") return hoursFromNow(spec.h + 2.2);
  if (spec.status === "postponed") return hoursFromNow(spec.h + 0.5);
  return null;
}

export const GAMES: Row<"games">[] = GAME_SPECS.map((spec, index) => {
  const settled = settledAt(spec);
  const live = spec.status === "live" ? hoursFromNow(-0.02) : null;
  return {
    id: demoId(ID.game, index + 1),
    fixture_id: FIRST_FIXTURE_ID + index,
    competition_id: spec.competitionId,
    home_team: spec.home,
    away_team: spec.away,
    home_logo: teamLogo(spec.home),
    away_logo: teamLogo(spec.away),
    kickoff_at: hoursFromNow(spec.h),
    status: spec.status,
    score_home: spec.score ? spec.score[0] : null,
    score_away: spec.score ? spec.score[1] : null,
    minute: spec.minute ?? null,
    live_updated_at: live,
    settled_at: settled,
    // Whatever touched the row last: the live poller, the settlement job, or
    // this morning's fixtures sync for anything still to come.
    updated_at: live ?? settled ?? hoursFromNow(-6),
  };
});

// ─── questions ─────────────────────────────────────────────────────────────

const QUESTION_TYPES: readonly QuestionType[] = ["match_result", "over_under_2_5", "btts"];

/**
 * When the questions were written.
 *
 * The daily sync pulls the whole season and upserts on `(game_id, type)`, so a
 * fixture's questions are created the first time it appears and keep that
 * timestamp for the rest of the season — months before kickoff for a match in
 * November. One constant is therefore more accurate than a per-fixture guess.
 */
const SEASON_SYNC_AT = hoursFromNow(-2184);

/**
 * Three questions per fixture, priced from the fixture's own odds tuple.
 *
 * Labels follow `buildQuestions()` exactly: the raw club name for the winner
 * market, Hebrew for the two that are not names. `correct_outcome` is not typed
 * in anywhere — it comes from `resolveOutcome()` with the score on the row, so
 * the three answers for a 2-2 are necessarily draw / over / yes.
 */
export const QUESTIONS: Row<"questions">[] = GAME_SPECS.flatMap((spec, gameIndex) => {
  const game = GAMES[gameIndex];
  const [home, draw, away, over, under, yes, no] = spec.odds;

  const outcomesByType: Record<QuestionType, { key: string; label: string; odds: number }[]> = {
    match_result: [
      { key: "home", label: spec.home, odds: home },
      { key: "draw", label: "תיקו", odds: draw },
      { key: "away", label: spec.away, odds: away },
    ],
    over_under_2_5: [
      { key: "over", label: "מעל 2.5 שערים", odds: over },
      { key: "under", label: "מתחת ל-2.5 שערים", odds: under },
    ],
    btts: [
      { key: "yes", label: "כן", odds: yes },
      { key: "no", label: "לא", odds: no },
    ],
  };

  return QUESTION_TYPES.map((type, typeIndex) => ({
    id: demoId(ID.question, (gameIndex + 1) * 10 + typeIndex),
    game_id: game.id,
    type,
    outcomes: outcomesByType[type] as unknown as Json,
    correct_outcome:
      spec.status === "finished" && spec.score
        ? resolveOutcome(type, spec.score[0], spec.score[1])
        : null,
    resolved_at: spec.status === "finished" ? game.settled_at : null,
    odds_provisional: spec.provisional ?? false,
    created_at: SEASON_SYNC_AT,
  }));
});

