export const ADVISOR_CONVERSATIONS: Row<"advisor_conversations">[] = CONVERSATIONS.map(
  (thread, index) => ({
    id: demoId(ID.conversation, index + 1),
    user_id: DEMO_USER_ID,
    game_id: GAME_ID[thread.key],
    created_at: hoursFromNow(thread.h),
    // Touched by the last message in the thread; two questions and two answers
    // apart, five minutes each, so the ordering is readable.
    updated_at: hoursFromNow(thread.h + thread.pairs.length * 0.5),
  }),
);

export const ADVISOR_MESSAGES: Row<"advisor_messages">[] = CONVERSATIONS.flatMap(
  (thread, threadIndex) =>
    thread.pairs.flatMap((pair, pairIndex) => {
      const conversationId = demoId(ID.conversation, threadIndex + 1);
      const base = thread.h + pairIndex * 0.5;
      const seq = (threadIndex + 1) * 100 + pairIndex * 2;
      return [
        {
          id: demoId(ID.message, seq + 1),
          conversation_id: conversationId,
          role: "user",
          content: pair.q,
          blocked: false,
          created_at: hoursFromNow(base),
        },
        {
          id: demoId(ID.message, seq + 2),
          conversation_id: conversationId,
          role: "assistant",
          content: pair.a,
          blocked: pair.blocked ?? false,
          created_at: hoursFromNow(base + 0.05),
        },
      ];
    }),
);

/**
 * The quota, as two rows.
 *
 * The primary key is `(user_id, usage_date)`, which is what lets
 * `advisor_consume_quota()` upsert atomically — two tabs must not both be told
 * they have the last question. Today sits below the ten-a-day limit so the
 * counter in the UI has something to count down from; yesterday is near the
 * ceiling, which is the state the limit exists for.
 */
export const ADVISOR_USAGE: Row<"advisor_usage">[] = [
  { user_id: DEMO_USER_ID, usage_date: hoursFromNow(0).slice(0, 10), question_count: 6 },
  { user_id: DEMO_USER_ID, usage_date: hoursFromNow(-24).slice(0, 10), question_count: 9 },
];
